CREATE TABLE public.relatorios_ocorrencias_recebimento (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), carga_entrada_id uuid NOT NULL REFERENCES public.cargas_entrada(id) ON DELETE RESTRICT, dados jsonb NOT NULL, registrado_por uuid, registrado_por_nome text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.relatorios_ocorrencias_recebimento TO authenticated; GRANT ALL ON public.relatorios_ocorrencias_recebimento TO service_role;
ALTER TABLE public.relatorios_ocorrencias_recebimento ENABLE ROW LEVEL SECURITY;
CREATE POLICY receiving_reports_read ON public.relatorios_ocorrencias_recebimento FOR SELECT TO authenticated USING(private.can_receive(auth.uid()));
CREATE POLICY receiving_reports_insert ON public.relatorios_ocorrencias_recebimento FOR INSERT TO authenticated WITH CHECK(private.can_receive(auth.uid()));
CREATE TABLE public.relatorio_ocorrencia_vinculos (relatorio_id uuid NOT NULL REFERENCES public.relatorios_ocorrencias_recebimento(id) ON DELETE RESTRICT, ocorrencia_id uuid NOT NULL REFERENCES public.ocorrencias(id) ON DELETE RESTRICT, PRIMARY KEY(relatorio_id,ocorrencia_id));
GRANT SELECT ON public.relatorio_ocorrencia_vinculos TO authenticated; GRANT ALL ON public.relatorio_ocorrencia_vinculos TO service_role;
ALTER TABLE public.relatorio_ocorrencia_vinculos ENABLE ROW LEVEL SECURITY;
CREATE POLICY receiving_links_read ON public.relatorio_ocorrencia_vinculos FOR SELECT TO authenticated USING(private.can_receive(auth.uid()));
CREATE FUNCTION public.tg_receiving_occurrence_report() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE c public.cargas_entrada; ids uuid[]; items jsonb; cpf text; nm text; v jsonb; k text; BEGIN
 IF NOT private.can_receive(auth.uid()) THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF;
 SELECT * INTO c FROM public.cargas_entrada WHERE id=NEW.carga_entrada_id FOR UPDATE;
 IF NOT FOUND OR c.situacao='excluida' THEN RAISE EXCEPTION 'Carga indisponível'; END IF;
 SELECT array_agg(DISTINCT value::uuid) INTO ids FROM jsonb_array_elements_text(NEW.dados->'ocorrencia_ids');
 IF cardinality(ids) IS NULL OR cardinality(ids)=0 OR (SELECT count(*) FROM public.ocorrencias o JOIN public.notas_fiscais n ON n.id=o.nota_id WHERE o.id=ANY(ids) AND o.origem='recebimento' AND o.carga_entrada_id=c.id AND n.carga_entrada_id=c.id)<>cardinality(ids) THEN RAISE EXCEPTION 'Ocorrências não pertencem ao recebimento desta carga'; END IF;
 PERFORM 1 FROM public.ocorrencias WHERE id=ANY(ids) ORDER BY id FOR SHARE;
 SELECT jsonb_agg(to_jsonb(o)||jsonb_build_object('numero_nf',n.numero,'fornecedor',n.fornecedor) ORDER BY o.data_ocorrencia,o.id) INTO items FROM public.ocorrencias o JOIN public.notas_fiscais n ON n.id=o.nota_id WHERE o.id=ANY(ids);
 SELECT m.cpf INTO cpf FROM public.veiculos ve JOIN public.motoristas m ON m.id=ve.motorista_id WHERE ve.id=c.veiculo_id AND lower(trim(m.nome))=lower(trim(c.motorista));
 SELECT coalesce(nullif(nome,''),email) INTO nm FROM public.profiles WHERE id=auth.uid();
 v:=jsonb_build_object('transporte',c.numero_transporte,'transportadora',c.transportadora,'motorista',coalesce(c.motorista,''),'placa',coalesce(c.placa,''),'cpf',coalesce(cpf,''),'data',coalesce(c.data_chegada::text,''),'conferente',coalesce(c.recebido_por_nome,''));
 FOREACH k IN ARRAY ARRAY['motorista','placa','cpf','data','conferente'] LOOP IF coalesce(v->>k,'')='' THEN v:=v||jsonb_build_object(k,coalesce(NEW.dados->'complementos'->>k,'')); END IF; END LOOP;
 NEW.dados:=v||jsonb_build_object('ocorrencia_ids',to_jsonb(ids),'ocorrencias',items); NEW.registrado_por:=auth.uid(); NEW.registrado_por_nome:=nm; NEW.created_at:=now(); RETURN NEW;
 END $$;
CREATE TRIGGER receiving_report_identity BEFORE INSERT ON public.relatorios_ocorrencias_recebimento FOR EACH ROW EXECUTE FUNCTION public.tg_receiving_occurrence_report();
CREATE FUNCTION public.tg_receiving_report_links() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN INSERT INTO public.relatorio_ocorrencia_vinculos(relatorio_id,ocorrencia_id) SELECT NEW.id,value::uuid FROM jsonb_array_elements_text(NEW.dados->'ocorrencia_ids'); INSERT INTO public.historico(entidade,entidade_id,acao,descricao,user_id) VALUES('carga_entrada',NEW.carga_entrada_id,'relatorio_ocorrencias','Relatório de ocorrências emitido: '||NEW.id,auth.uid()); RETURN NEW; END $$;
CREATE TRIGGER receiving_report_links AFTER INSERT ON public.relatorios_ocorrencias_recebimento FOR EACH ROW EXECUTE FUNCTION public.tg_receiving_report_links();
CREATE TABLE public.anexos_recebimento_assinados (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), carga_entrada_id uuid NOT NULL REFERENCES public.cargas_entrada(id) ON DELETE RESTRICT, recibo_id uuid REFERENCES public.documentos_recebimento(id) ON DELETE RESTRICT, relatorio_id uuid REFERENCES public.relatorios_ocorrencias_recebimento(id) ON DELETE RESTRICT, storage_path text NOT NULL UNIQUE, nome_arquivo text NOT NULL, mime_type text NOT NULL, versao integer NOT NULL DEFAULT 1, registrado_por uuid, registrado_por_nome text, created_at timestamptz NOT NULL DEFAULT now(), CHECK(num_nonnulls(recibo_id,relatorio_id)=1));
GRANT SELECT, INSERT ON public.anexos_recebimento_assinados TO authenticated; GRANT ALL ON public.anexos_recebimento_assinados TO service_role;
ALTER TABLE public.anexos_recebimento_assinados ENABLE ROW LEVEL SECURITY;
CREATE POLICY signed_receiving_read ON public.anexos_recebimento_assinados FOR SELECT TO authenticated USING(private.can_receive(auth.uid()));
CREATE POLICY signed_receiving_insert ON public.anexos_recebimento_assinados FOR INSERT TO authenticated WITH CHECK(private.can_receive(auth.uid()));
CREATE FUNCTION public.tg_signed_receiving_identity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE cid uuid; nm text; target uuid:=coalesce(NEW.recibo_id,NEW.relatorio_id); previous integer; BEGIN
 IF NOT private.can_receive(auth.uid()) THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF;
 IF NEW.recibo_id IS NOT NULL THEN SELECT carga_entrada_id INTO cid FROM public.documentos_recebimento WHERE id=NEW.recibo_id AND tipo='recibo'; ELSE SELECT carga_entrada_id INTO cid FROM public.relatorios_ocorrencias_recebimento WHERE id=NEW.relatorio_id; END IF;
 IF cid IS NULL OR cid<>NEW.carga_entrada_id THEN RAISE EXCEPTION 'Documento não pertence à carga'; END IF;
 PERFORM 1 FROM public.cargas_entrada WHERE id=cid FOR UPDATE;
 PERFORM pg_advisory_xact_lock(hashtextextended(target::text,0));
 SELECT coalesce(max(versao),0) INTO previous FROM public.anexos_recebimento_assinados WHERE coalesce(recibo_id,relatorio_id)=target;
 IF previous>0 AND NOT private.has_role(auth.uid(),'administrador') THEN RAISE EXCEPTION 'Somente administrador pode substituir o anexo'; END IF;
 IF NEW.storage_path<>auth.uid()::text||'/'||NEW.id::text OR NEW.mime_type NOT IN ('image/jpeg','image/png','image/webp','application/pdf') OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='recebimento-assinados' AND name=NEW.storage_path AND metadata->>'mimetype'=NEW.mime_type AND (metadata->>'size')::bigint<=15728640) THEN RAISE EXCEPTION 'Arquivo inválido ou não enviado'; END IF;
 SELECT coalesce(nullif(nome,''),email) INTO nm FROM public.profiles WHERE id=auth.uid(); NEW.versao:=previous+1; NEW.registrado_por:=auth.uid(); NEW.registrado_por_nome:=nm; NEW.created_at:=now();
 INSERT INTO public.historico(entidade,entidade_id,acao,descricao,user_id) VALUES('carga_entrada',cid,'documento_assinado','Arquivo assinado anexado — versão '||NEW.versao||' — '||NEW.nome_arquivo,auth.uid()); RETURN NEW; END $$;
CREATE TRIGGER signed_receiving_identity BEFORE INSERT ON public.anexos_recebimento_assinados FOR EACH ROW EXECUTE FUNCTION public.tg_signed_receiving_identity();
CREATE POLICY receiving_signed_storage_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='recebimento-assinados' AND private.can_receive(auth.uid()) AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY receiving_signed_storage_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='recebimento-assinados' AND private.can_receive(auth.uid()) AND EXISTS(SELECT 1 FROM public.anexos_recebimento_assinados a WHERE a.storage_path=name));
CREATE TABLE public.recibo_recebimento_eventos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recibo_id uuid NOT NULL REFERENCES public.documentos_recebimento(id) ON DELETE RESTRICT UNIQUE, motivo text NOT NULL, registrado_por uuid, registrado_por_nome text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.recibo_recebimento_eventos TO authenticated; GRANT ALL ON public.recibo_recebimento_eventos TO service_role; ALTER TABLE public.recibo_recebimento_eventos ENABLE ROW LEVEL SECURITY;
CREATE POLICY receiving_receipt_events_read ON public.recibo_recebimento_eventos FOR SELECT TO authenticated USING(private.can_receive(auth.uid()));
CREATE POLICY receiving_receipt_events_insert ON public.recibo_recebimento_eventos FOR INSERT TO authenticated WITH CHECK(private.has_role(auth.uid(),'administrador'));
CREATE FUNCTION public.tg_receiving_receipt_cancel() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE cid uuid; BEGIN IF NOT private.has_role(auth.uid(),'administrador') OR length(trim(NEW.motivo))<3 THEN RAISE EXCEPTION 'Cancelamento exige administrador e justificativa'; END IF; SELECT carga_entrada_id INTO cid FROM public.documentos_recebimento WHERE id=NEW.recibo_id AND tipo='recibo'; IF cid IS NULL THEN RAISE EXCEPTION 'Recibo inválido'; END IF; PERFORM 1 FROM public.cargas_entrada WHERE id=cid FOR UPDATE; NEW.registrado_por:=auth.uid(); SELECT nome INTO NEW.registrado_por_nome FROM public.profiles WHERE id=auth.uid(); NEW.created_at:=now(); INSERT INTO public.historico(entidade,entidade_id,acao,descricao,user_id) VALUES('carga_entrada',cid,'recibo_cancelado',NEW.motivo,auth.uid()); RETURN NEW; END $$;
CREATE TRIGGER receiving_receipt_cancel BEFORE INSERT ON public.recibo_recebimento_eventos FOR EACH ROW EXECUTE FUNCTION public.tg_receiving_receipt_cancel();